        public IEnumerable<IFormLinkGetter> EnumerateFormLinks(IWeatherGetter obj, bool iterateNestedRecords = true)
        {
            foreach (var item in base.EnumerateFormLinks(obj, iterateNestedRecords))
            {
                yield return item;
            }
            if (FormLinkInformation.TryFactory(obj.ImageSpaceSunrise, out var ImageSpaceSunriseInfo))
            {
                yield return ImageSpaceSunriseInfo;
            }
            if (FormLinkInformation.TryFactory(obj.ImageSpaceDay, out var ImageSpaceDayInfo))
            {
                yield return ImageSpaceDayInfo;
            }
            if (FormLinkInformation.TryFactory(obj.ImageSpaceSunset, out var ImageSpaceSunsetInfo))
            {
                yield return ImageSpaceSunsetInfo;
            }
            if (FormLinkInformation.TryFactory(obj.ImageSpaceNight, out var ImageSpaceNightInfo))
            {
                yield return ImageSpaceNightInfo;
            }
            if (obj.Model is {} ModelItems)
            {
                foreach (var item in ModelItems.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            foreach (var item in obj.Sounds.SelectMany(f => f.EnumerateFormLinks(iterateNestedRecords)))
            {
                yield return FormLinkInformation.Factory(item);
            }
            yield break;
        }
        
